usage() {
  cat <<'EOF'
Usage: migrate-values-3-to-4.sh --target {3|4} [OPTIONS] [INPUT ...]

Move Big Bang 3.x built-in package configuration from top-level and
addons.<name> paths to the Big Bang 4.x packages.<name> paths. With target 4,
istio, networkPolicies, and routes values for built-in packages are also moved
under the bb-common subchart key. Unless omitted for a secondary values
source, the output sets packageConfiguration.version to v1.
Target 4 also converts recognized legacy Istio host lists, including
packages.<name>.istio.hosts for single-route built-ins, to
packages.<name>.values.bb-common.routes.inbound.<route>.hosts. Explicit route
hosts win. Ambiguous or custom-package hosts are preserved and reported for
manual migration; a flat host list is never copied to multiple endpoints.
Legacy {{ .Values.domain }} hostname templates are translated to the bb-common
global domain context. Other Helm templates are retained for manual review.
Starting with Big Bang 3.32, the 3.x chart uses it to interpret catalog package
names as canonical built-ins rather than existing custom packages.
Big Bang 4.x retains v1 as the default unified package contract; do not remove
it from the migrated output when upgrading.
Target 3 performs only the unified package-path migration and retains the flat
bb-common library values and legacy hardening used by Big Bang 3.x. Target 4
also converts bb-common values to the subchart layout and removes legacy
hardening for Big Bang 4.x. Target 4 output must not be deployed to a 3.x
release.

Inputs are composed in order using Helm values precedence (later files win),
then migrated into one consolidated document. By default, migrated YAML is
written to standard output and the inputs are unchanged.
Package entries retain their first-appearance order in the composed input.
With --secret-key, exactly one decrypted Kubernetes Secret is accepted and its
envelope is preserved around the migrated values payload.
With --bigbang-helmrelease, exactly one parent Big Bang HelmRelease or patch is
accepted. Only its inline spec.values are migrated; the wrapper, valuesFrom,
postRenderers, and other fields are preserved. Files without inline values
remain unchanged. Use --omit-package-configuration for secondary patches.
YAML anchors and aliases are expanded automatically and their anchor names are
reported. Expansion must preserve the resolved values structure.
Package HelmRelease patches can be supplied with --helmrelease-patch. Their
spec.values and supported Flux settings override the migrated values inputs;
later patches win. Output is Big Bang values, not a HelmRelease manifest.
Supported spec fields: values, interval, timeout, install, upgrade, rollback,
uninstall, test, driftDetection, suspend, maxHistory, persistentClient, and
serviceAccountName. Other fields, nulls, and patch directives require manual
migration. --helmrelease-patch cannot be combined with --in-place or --secret-key.

Options:
  -t, --target {3|4}               Required target Big Bang major version.
  -o, --output FILE               Write migrated values to FILE.
  -i, --in-place                  Replace a single INPUT after creating
                                  INPUT.bak.
  -k, --secret-key KEY            Migrate values stored at data[KEY] or
                                  stringData[KEY] in one decrypted Kubernetes
                                  Secret.
      --helmrelease-patch FILE    Convert a package HelmRelease patch to values.
                                  Repeat for multiple files; each file may
                                  contain multiple HelmRelease documents.
      --bigbang-helmrelease       Migrate inline spec.values in one parent
                                  Big Bang HelmRelease, preserving its wrapper.
      --omit-package-configuration
                                  Remove packageConfiguration from the output.
                                  Use only for a secondary values source when
                                  another composed source supplies
                                  packageConfiguration.version v1.
  -h, --help                      Show this help.

If both a legacy path and packages.<name> exist, they are recursively merged
and packages.<name> takes precedence. Unrecognized package entries are left
unchanged. The migration is idempotent.

Examples:
  scripts/migrate-values-3-to-4.sh --target 3 -o values-v1.yaml values.yaml
  scripts/migrate-values-3-to-4.sh --target 4 -o values-4.x.yaml values.yaml
  scripts/migrate-values-3-to-4.sh --target 4 -o values-4.x.yaml base.yaml production.yaml
  scripts/migrate-values-3-to-4.sh --target 4 values.yaml > values-4.x.yaml
  scripts/migrate-values-3-to-4.sh --target 4 --in-place values.yaml
  scripts/migrate-values-3-to-4.sh --target 4 --secret-key values.yaml secret.yaml
  scripts/migrate-values-3-to-4.sh --target 4 --bigbang-helmrelease \
    --omit-package-configuration -o monitoring-4.x.yaml monitoring.yaml
  scripts/migrate-values-3-to-4.sh --target 4 -o values-4.x.yaml values.yaml \
    --helmrelease-patch monitoring.yaml --helmrelease-patch ek.yaml
  scripts/migrate-values-3-to-4.sh --target 4 --omit-package-configuration \
    --output overlay-4.x.yaml overlay.yaml

For values embedded in a SOPS-encrypted Kubernetes Secret, use
scripts/migrate-sops-values-3-to-4.sh.
EOF
}

fail() {
  printf 'Error: %s\n' "$*" >&2
  exit 1
}

decode_base64() {
  if printf '' | base64 --decode >/dev/null 2>&1; then
    base64 --decode
  else
    base64 -D
  fi
}

lower_package_name() {
  printf '%s' "$1" | tr '[:upper:]' '[:lower:]'
}

# Mirror the chart's resourceName helper for package-name collision checks:
# replace non-word runs, trim and truncate, then apply Sprig's kebab casing.
package_resource_name() {
  printf '%s' "$1" \
    | sed -E 's/[^[:alnum:]_]+/-/g; s/^-//' \
    | cut -c 1-63 \
    | sed -E 's/-$//; s/([[:upper:]]+)([[:upper:]][[:lower:]])/\1-\2/g; s/([[:lower:][:digit:]])([[:upper:]])/\1-\2/g; s/_/-/g' \
    | tr '[:upper:]' '[:lower:]'
}

is_builtin_package() {
  local candidate=$1
  local package_name

  for package_name in "${ROOT_PACKAGES[@]}" "${ADDON_PACKAGES[@]}"; do
    [[ "$candidate" == "$package_name" ]] && return 0
  done
  return 1
}

is_root_package() {
  local candidate=$1
  local package_name

  for package_name in "${ROOT_PACKAGES[@]}"; do
    [[ "$candidate" == "$package_name" ]] && return 0
  done
  return 1
}

is_addon_package() {
  local candidate=$1
  local package_name

  [[ "$candidate" == "mattermostoperator" ]] && return 0
  for package_name in "${ADDON_PACKAGES[@]}"; do
    [[ "$candidate" == "$package_name" ]] && return 0
  done
  return 1
}

append_package_order() {
  local candidate=$1
  local package_name

  if (( ${#PACKAGE_ORDER[@]} != 0 )); then
    for package_name in "${PACKAGE_ORDER[@]}"; do
      [[ "$candidate" == "$package_name" ]] && return 0
    done
  fi

  PACKAGE_ORDER+=("$candidate")
}

capture_package_order() {
  local values_file=$1
  local top_level_name
  local package_name

  PACKAGE_ORDER=()
  while IFS= read -r top_level_name; do
    if is_root_package "$top_level_name"; then
      append_package_order "$top_level_name"
    elif [[ "$top_level_name" == "addons" ]]; then
      while IFS= read -r package_name; do
        if is_addon_package "$package_name"; then
          [[ "$package_name" == "mattermostoperator" ]] \
            && package_name=mattermostOperator
          append_package_order "$package_name"
        fi
      done < <(yq -r '.addons // {} | to_entries | .[].key' "$values_file")
    elif [[ "$top_level_name" == "packages" ]]; then
      while IFS= read -r package_name; do
        append_package_order "$package_name"
      done < <(yq -r '.packages // {} | to_entries | .[].key' "$values_file")
    fi
  done < <(yq -r 'to_entries | .[].key' "$values_file")
}

reorder_packages() {
  local values_file=$1
  local package_name
  local package_order_yaml

  while IFS= read -r package_name; do
    append_package_order "$package_name"
  done < <(yq -r '.packages // {} | to_entries | .[].key' "$values_file")

  [[ ${#PACKAGE_ORDER[@]} -gt 0 ]] || return 0
  package_order_yaml=$(printf '%s\n' "${PACKAGE_ORDER[@]}" \
    | jq -Rn '[inputs]' \
    | yq -P)
  PACKAGE_ORDER_YAML="$package_order_yaml" yq -i '
    .packages as $packages |
    ($packages | to_entries) as $entries |
    (env(PACKAGE_ORDER_YAML) |
      map(. as $name | $entries[] | select(.key == $name)) |
      from_entries) as $ordered |
    .packages = $ordered |
    .packages style=""
  ' "$values_file"
}

validate_values_file() {
  local values_file=$1
  local display_name=${2:-$1}
  local document_count

  document_count=$(yq eval-all --no-doc '1' "$values_file" 2>/dev/null | wc -l | tr -d '[:space:]') \
    || fail "input is not valid YAML: $display_name"
  [[ "$document_count" == "1" ]] \
    || fail "multiple YAML documents are not supported: $display_name"
  yq -e 'tag == "!!map"' "$values_file" >/dev/null 2>&1 \
    || fail "the values document root must be a YAML mapping: $display_name"
  yq -e '.kind == "HelmRelease"' "$values_file" >/dev/null 2>&1 \
    && fail "use --helmrelease-patch for a package HelmRelease or --bigbang-helmrelease for a parent Big Bang HelmRelease: $display_name"
  yq -e 'has("sops") and (.sops | tag == "!!map")' "$values_file" >/dev/null 2>&1 \
    && fail "SOPS-encrypted input is not supported by this command: $display_name; use scripts/migrate-sops-values-3-to-4.sh"
  yq --yaml-fix-merge-anchor-to-spec=true -e \
    'explode(.) | ((.packages == null) or (.packages | tag == "!!map"))' "$values_file" >/dev/null 2>&1 \
    || fail "packages must be a YAML mapping: $display_name"
  yq --yaml-fix-merge-anchor-to-spec=true -e \
    'explode(.) | ((.addons == null) or (.addons | tag == "!!map"))' "$values_file" >/dev/null 2>&1 \
    || fail "addons must be a YAML mapping: $display_name"
  yq --yaml-fix-merge-anchor-to-spec=true -e \
    'explode(.) | ((.packageConfiguration == null) or (.packageConfiguration | tag == "!!map"))' "$values_file" >/dev/null 2>&1 \
    || fail "packageConfiguration must be a YAML mapping: $display_name"
  yq --yaml-fix-merge-anchor-to-spec=true -e \
    'explode(.) | ((.packageConfiguration.version == null) or (.packageConfiguration.version == "v1"))' "$values_file" >/dev/null 2>&1 \
    || fail "packageConfiguration.version must be v1: $display_name"
}

validate_bigbang_helmrelease_file() {
  local input_file=$1
  local document_count

  document_count=$(yq eval-all --no-doc '1' "$input_file" 2>/dev/null | wc -l | tr -d '[:space:]') \
    || fail "input is not valid YAML: $input_file"
  [[ "$document_count" == "1" ]] \
    || fail "--bigbang-helmrelease requires exactly one YAML document: $input_file"
  yq -e 'tag == "!!map"' "$input_file" >/dev/null 2>&1 \
    || fail "the HelmRelease document root must be a YAML mapping: $input_file"
  yq -e 'has("sops")' "$input_file" >/dev/null 2>&1 \
    && fail "--bigbang-helmrelease requires a decrypted HelmRelease: $input_file"
  yq --yaml-fix-merge-anchor-to-spec=true -e 'explode(.) |
    .kind == "HelmRelease" and
    (.apiVersion == "helm.toolkit.fluxcd.io/v2" or
     .apiVersion == "helm.toolkit.fluxcd.io/v2beta2" or
     .apiVersion == "helm.toolkit.fluxcd.io/v2beta1") and
    (.metadata.name | tag == "!!str") and (.metadata.name | length > 0) and
    (.spec | tag == "!!map")' "$input_file" >/dev/null 2>&1 \
    || fail "--bigbang-helmrelease input must be a Flux HelmRelease with metadata.name and a spec mapping: $input_file"
  yq --yaml-fix-merge-anchor-to-spec=true -e 'explode(.) |
    ((.spec | has("values") | not) or (.spec.values | tag == "!!map"))' "$input_file" >/dev/null 2>&1 \
    || fail "inline spec.values must be a mapping; null deletions require manual migration: $input_file"
}

# Inputs have already been composed and package/chart-value aliases normalized.
# Only inspect direct hosts and immediate endpoint hosts: ServiceEntry hosts,
# outbound routes, upstream ingress, and other nested configuration are not
# legacy inbound endpoint overrides.
migrate_inbound_hosts() {
  local candidate package_name endpoint source_path istio_path source_display host_route
  local mapping mapping_package mapping_endpoint mapping_route ambiguous
  local destination_present blocked blocked_route route_identity
  local blocked_routes=()
  local candidates_file="$PATCH_WORK_DIR/host-candidates.jsonl"
  local translated_hosts_file="$PATCH_WORK_DIR/translated-hosts.json"

  yq -o=json '.' "$WORK_FILE" | jq -c '
    def object_at($path):
      reduce $path[] as $key (.; if type == "object" then .[$key] else null end);
    [.packages // {} | to_entries[] | .key as $package | .value as $config |
      select($config | type == "object") |
      ([($config | object_at(["values", "bb-common", "istio"])),
        ["packages", $package, "values", "bb-common", "istio"], 0],
       [($config | object_at(["values", "istio"])), ["packages", $package, "values", "istio"], 1],
       [$config.istio, ["packages", $package, "istio"], 2]) |
      .[0] as $istio | .[1] as $path | .[2] as $priority |
      select($istio | type == "object") |
      (if $istio | has("hosts") then
         {endpoint: "__flat__", path: $path, hosts: $istio.hosts, flat: 1}
       else empty end),
      ($istio | to_entries[] | select(.value | type == "object" and has("hosts")) |
        {endpoint: .key, path: ($path + [.key]), hosts: .value.hosts, flat: 0}) |
      . + {package: $package, priority: $priority, istioPath: $path} |
      .source = ("." + (.path | map("[" + tojson + "]") | join(""))) |
      .istioSource = ("." + (.istioPath | map("[" + tojson + "]") | join(""))) |
      .display = ((.path + ["hosts"]) | join("."))] |
    sort_by(.priority, .flat) | .[]
  ' >"$candidates_file"

  while IFS= read -r candidate; do
    package_name=$(jq -r '.package' <<<"$candidate")
    endpoint=$(jq -r '.endpoint' <<<"$candidate")
    source_path=$(jq -r '.source' <<<"$candidate")
    istio_path=$(jq -r '.istioSource' <<<"$candidate")
    source_display=$(jq -r '.display' <<<"$candidate")
    host_route=""
    ambiguous=false
    for mapping in "${INBOUND_HOST_MAPPINGS[@]}"; do
      IFS='|' read -r mapping_package mapping_endpoint mapping_route <<<"$mapping"
      [[ "$package_name" == "$mapping_package" ]] || continue
      if [[ "$endpoint" == __flat__ ]]; then
        if [[ -n "$host_route" && "$host_route" != "$mapping_route" ]]; then
          ambiguous=true
        fi
        host_route=$mapping_route
      elif [[ "$endpoint" == "$mapping_endpoint" ]]; then
        host_route=$mapping_route
      fi
    done

    if [[ -z "$host_route" || "$ambiguous" == true ]]; then
      HOST_MIGRATION_REVIEW+=("$source_display: no unambiguous built-in endpoint mapping; hosts preserved. Set packages.$package_name.values.bb-common.routes.inbound.<route>.hosts explicitly, then remove the legacy hosts key.")
      continue
    fi

    jq -e '.hosts == null or
      (.hosts | type == "array" and all(.[]; type == "string" and length > 0))' \
      <<<"$candidate" >/dev/null \
      || fail "$source_display must be a list of non-empty strings or null; migrate this hostname override manually; no output written"

    if jq -e '.hosts != null and .hosts != []' <<<"$candidate" >/dev/null; then
      # Refuse structural deletions or malformed route ancestors instead of
      # overwriting them with maps. A hosts key itself, even [] or null, wins.
      yq -o=json '.' "$WORK_FILE" | jq -e --arg package "$package_name" --arg route "$host_route" '
        def mapping_path($path):
          if type != "object" then false
          elif ($path | length) == 0 then true
          elif has($path[0]) then .[$path[0]] | mapping_path($path[1:])
          else true end;
        .packages[$package] | mapping_path(["values", "bb-common", "routes", "inbound", $route])
      ' >/dev/null \
        || fail "$source_display cannot be migrated into packages.$package_name.values.bb-common.routes.inbound.$host_route: destination ancestors must be mappings; migrate manually; no output written"

      destination_present=$(PACKAGE_NAME="$package_name" HOST_ROUTE="$host_route" yq -r '
        (.packages[strenv(PACKAGE_NAME)].values.bb-common.routes.inbound[strenv(HOST_ROUTE)] // {}) | has("hosts")
      ' "$WORK_FILE")
      route_identity="$package_name|$host_route"
      blocked=false
      if [[ ${#blocked_routes[@]} -gt 0 ]]; then
        for blocked_route in "${blocked_routes[@]}"; do
          [[ "$blocked_route" == "$route_identity" ]] && blocked=true
        done
      fi

      if [[ "$destination_present" != true ]]; then
        if [[ "$blocked" == true ]]; then
          HOST_MIGRATION_REVIEW+=("$source_display: a higher-precedence legacy hostname override requires manual template migration; hosts preserved. Resolve all legacy hosts for packages.$package_name.values.bb-common.routes.inbound.$host_route.hosts.")
          continue
        fi

        if yq -o=json '.' "$WORK_FILE" | jq -e --arg package "$package_name" '
          .packages[$package].values |
          type == "object" and (has("domain") or (.global | type == "object" and has("domain")))
        ' >/dev/null && jq -e '
          [.hosts[] | select(test("\\{\\{-?\\s*\\.Values\\.domain\\s*-?\\}\\}"))] | length > 0
        ' <<<"$candidate" >/dev/null; then
          blocked_routes+=("$route_identity")
          HOST_MIGRATION_REVIEW+=("$source_display: packages.$package_name.values.domain or values.global.domain overrides a template context; hosts preserved. Set packages.$package_name.values.bb-common.routes.inbound.$host_route.hosts manually using the intended domain.")
          continue
        fi

        # These umbrella integrations do not pass the umbrella domain as the
        # child chart's global.domain. Argo CD instead derives it from its host.
        case "$package_name" in
          argocd|kyvernoReporter|mimir|minio|sonarqube)
            if jq -e '[.hosts[] | select(test("\\{\\{-?\\s*\\.Values\\.(global\\.)?domain\\s*-?\\}\\}"))] | length > 0' \
              <<<"$candidate" >/dev/null; then
              blocked_routes+=("$route_identity")
              HOST_MIGRATION_REVIEW+=("$source_display: the package does not expose the umbrella domain as bb-common global.domain; hosts preserved. Set packages.$package_name.values.bb-common.routes.inbound.$host_route.hosts manually using the package's target values context.")
              continue
            fi
            ;;
        esac

        # A child-chart route is evaluated in bb-common's values context.
        # Only direct domain references can be translated without evaluating
        # user-supplied templates; all other actions must be reviewed manually.
        if ! jq -e '
          [.hosts[] | gsub("\\{\\{-?\\s*\\.Values\\.(global\\.)?domain\\s*-?\\}\\}"; "") |
            select(test("\\{\\{|\\}\\}"))] | length == 0
        ' <<<"$candidate" >/dev/null; then
          blocked_routes+=("$route_identity")
          HOST_MIGRATION_REVIEW+=("$source_display: unsupported Helm template; hosts preserved. Translate the template for the bb-common values context and set packages.$package_name.values.bb-common.routes.inbound.$host_route.hosts manually.")
          continue
        fi

        jq '.hosts | map(gsub("\\{\\{(?<left>-?)\\s*\\.Values\\.domain\\s*(?<right>-?)\\}\\}";
          "{{\(.left) .Values.global.domain \(.right)}}"))' <<<"$candidate" >"$translated_hosts_file"
        PACKAGE_NAME="$package_name" HOST_ROUTE="$host_route" HOSTS_FILE="$translated_hosts_file" yq -i '
          .packages[strenv(PACKAGE_NAME)].values.bb-common.routes.inbound[strenv(HOST_ROUTE)].hosts =
            load(strenv(HOSTS_FILE))
        ' "$WORK_FILE"
      fi
      MIGRATED_PATHS+=("$source_display -> packages.$package_name.values.bb-common.routes.inbound.$host_route.hosts (explicit route hosts take precedence)")
    else
      MIGRATED_PATHS+=("$source_display -> removed empty legacy hosts (no route created)")
    fi

    HOST_SOURCE="$source_path" HOST_ISTIO_SOURCE="$istio_path" yq -i '
      del(eval(strenv(HOST_SOURCE)).hosts) |
      del(eval(strenv(HOST_SOURCE)) | select(tag == "!!map" and length == 0)) |
      del(eval(strenv(HOST_ISTIO_SOURCE)) | select(tag == "!!map" and length == 0))
    ' "$WORK_FILE"
  done <"$candidates_file"
}

OUTPUT_FILE=""
IN_PLACE=false
SECRET_VALUES_KEY=""
BIGBANG_HELMRELEASE=false
OMIT_PACKAGE_CONFIGURATION=false
TARGET_VERSION=""
INPUT_FILES=()
HELMRELEASE_PATCH_FILES=()
ALL_INPUT_FILES=()

while [[ $# -gt 0 ]]; do
  case "$1" in
    -t|--target)
      [[ $# -ge 2 ]] || fail "$1 requires 3 or 4"
      [[ -z "$TARGET_VERSION" ]] || fail "--target may only be specified once"
      case "$2" in
        3|4) TARGET_VERSION=$2 ;;
        *) fail "$1 must be 3 or 4" ;;
      esac
      shift 2
      ;;
    -o|--output)
      [[ $# -ge 2 ]] || fail "$1 requires a file path"
      OUTPUT_FILE=$2
      shift 2
      ;;
    -i|--in-place)
      IN_PLACE=true
      shift
      ;;
    -k|--secret-key)
      [[ $# -ge 2 ]] || fail "$1 requires a Secret key"
      [[ -n "$2" ]] || fail "$1 requires a non-empty Secret key"
      SECRET_VALUES_KEY=$2
      shift 2
      ;;
    --helmrelease-patch)
      [[ $# -ge 2 && -n "$2" ]] || fail "$1 requires a file path"
      HELMRELEASE_PATCH_FILES+=("$2")
      ALL_INPUT_FILES+=("$2")
      shift 2
      ;;
    --bigbang-helmrelease)
      BIGBANG_HELMRELEASE=true
      shift
      ;;
    --omit-package-configuration)
      OMIT_PACKAGE_CONFIGURATION=true
      shift
      ;;
    -h|--help)
      usage
      exit 0
      ;;
    -*)
      fail "unknown option: $1"
      ;;
    *)
      INPUT_FILES+=("$1")
      ALL_INPUT_FILES+=("$1")
      shift
      ;;
  esac
done

[[ -n "$TARGET_VERSION" ]] || fail "--target is required and must be 3 or 4"
[[ ${#INPUT_FILES[@]} -gt 0 || ${#HELMRELEASE_PATCH_FILES[@]} -gt 0 ]] \
  || fail "at least one input values file or --helmrelease-patch is required"
[[ -z "$SECRET_VALUES_KEY" || ${#INPUT_FILES[@]} -eq 1 ]] \
  || fail "--secret-key requires exactly one input Secret"
if [[ "$BIGBANG_HELMRELEASE" == true ]]; then
  [[ ${#INPUT_FILES[@]} -eq 1 ]] || fail "--bigbang-helmrelease requires exactly one input HelmRelease"
  [[ -z "$SECRET_VALUES_KEY" && ${#HELMRELEASE_PATCH_FILES[@]} -eq 0 ]] \
    || fail "--bigbang-helmrelease cannot be combined with --secret-key or --helmrelease-patch"
fi
if [[ ${#HELMRELEASE_PATCH_FILES[@]} -gt 0 ]]; then
  [[ -z "$SECRET_VALUES_KEY" ]] || fail "--helmrelease-patch cannot be combined with --secret-key"
  [[ "$IN_PLACE" != true ]] || fail "--helmrelease-patch cannot be combined with --in-place; write a separate values file with --output"
fi
command -v yq >/dev/null 2>&1 || fail "Mike Farah yq v4 is required"
[[ "$(yq --version 2>/dev/null)" =~ version\ v4\. ]] || fail "Mike Farah yq v4 is required"
yq --yaml-fix-merge-anchor-to-spec=true --null-input '.' >/dev/null 2>&1 \
  || fail "Mike Farah yq v4.47.1 or newer with --yaml-fix-merge-anchor-to-spec support is required"
command -v jq >/dev/null 2>&1 || fail "jq is required"

if [[ "$IN_PLACE" == true && -n "$OUTPUT_FILE" ]]; then
  fail "--in-place and --output cannot be used together"
fi
if [[ "$IN_PLACE" == true && ${#INPUT_FILES[@]} -ne 1 ]]; then
  fail "--in-place requires exactly one input file"
fi
if [[ -n "$OUTPUT_FILE" && -d "$OUTPUT_FILE" ]]; then
  fail "output path must be a file, not a directory: $OUTPUT_FILE"
fi

# Bash 3.2 treats an empty array as unset under nounset, so guard optional lists.
if [[ ${#INPUT_FILES[@]} -gt 0 ]]; then
  for input_file in "${INPUT_FILES[@]}"; do
    [[ -f "$input_file" ]] || fail "input file does not exist: $input_file"
    [[ -r "$input_file" ]] || fail "input file is not readable: $input_file"

    if [[ "$BIGBANG_HELMRELEASE" == true ]]; then
      validate_bigbang_helmrelease_file "$input_file"
    elif [[ -n "$SECRET_VALUES_KEY" ]]; then
      document_count=$(yq eval-all --no-doc '1' "$input_file" 2>/dev/null | wc -l | tr -d '[:space:]') \
        || fail "input is not valid YAML: $input_file"
      [[ "$document_count" == "1" ]] \
        || fail "multiple YAML documents are not supported: $input_file"
      yq -e 'tag == "!!map"' "$input_file" >/dev/null 2>&1 \
        || fail "the Secret document root must be a YAML mapping: $input_file"
      yq -e 'has("sops") and (.sops | tag == "!!map")' "$input_file" >/dev/null 2>&1 \
        && fail "SOPS-encrypted input is not supported by this command: $input_file; use scripts/migrate-sops-values-3-to-4.sh"
      yq -e '.kind == "Secret"' "$input_file" >/dev/null 2>&1 \
        || fail "--secret-key input must be a Kubernetes Secret: $input_file"
      yq --yaml-fix-merge-anchor-to-spec=true -e \
        'explode(.) | ((.stringData == null) or ((.stringData | tag) == "!!map"))' "$input_file" >/dev/null 2>&1 \
        || fail "Secret stringData must be a mapping: $input_file"
      yq --yaml-fix-merge-anchor-to-spec=true -e \
        'explode(.) | ((.data == null) or ((.data | tag) == "!!map"))' "$input_file" >/dev/null 2>&1 \
        || fail "Secret data must be a mapping: $input_file"
    else
      validate_values_file "$input_file"
    fi
  done
fi

if [[ ${#HELMRELEASE_PATCH_FILES[@]} -gt 0 ]]; then
  for input_file in "${HELMRELEASE_PATCH_FILES[@]}"; do
    [[ -f "$input_file" && -r "$input_file" ]] || fail "HelmRelease patch is not a readable file: $input_file"
  done
fi

if [[ -n "$OUTPUT_FILE" ]]; then
  for input_file in "${ALL_INPUT_FILES[@]}"; do
    if [[ "$OUTPUT_FILE" == "$input_file" ]] \
      || [[ -e "$OUTPUT_FILE" && "$OUTPUT_FILE" -ef "$input_file" ]]; then
      fail "output refers to an input file; use --in-place with a single input to replace it safely"
    fi
  done
fi

umask 077
WORK_FILE=$(mktemp "${TMPDIR:-/tmp}/bigbang-values-migration.XXXXXX")
SECRET_WORK_FILE=$(mktemp "${TMPDIR:-/tmp}/bigbang-secret-migration.XXXXXX")
SECRET_VALUE_FILE=$(mktemp "${TMPDIR:-/tmp}/bigbang-secret-value.XXXXXX")
BASE64_INPUT=$(mktemp "${TMPDIR:-/tmp}/bigbang-secret-base64.XXXXXX")
EXPANDED_FILE=$(mktemp "${TMPDIR:-/tmp}/bigbang-values-expanded.XXXXXX")
BEFORE_EXPANSION_JSON=$(mktemp "${TMPDIR:-/tmp}/bigbang-values-before-expansion.XXXXXX")
AFTER_EXPANSION_JSON=$(mktemp "${TMPDIR:-/tmp}/bigbang-values-after-expansion.XXXXXX")
PATCH_WORK_DIR=$(mktemp -d "${TMPDIR:-/tmp}/bigbang-helmrelease-migration.XXXXXX")
trap 'rm -f "$WORK_FILE" "$SECRET_WORK_FILE" "$SECRET_VALUE_FILE" "$BASE64_INPUT" "$EXPANDED_FILE" "$BEFORE_EXPANSION_JSON" "$AFTER_EXPANSION_JSON"; rm -rf "$PATCH_WORK_DIR"' EXIT

expand_yaml_anchors() {
  local values_file=$1
  local display_name=$2
  local anchor_name
  local anchor_names_output
  local anchor_names=()

  anchor_names_output=$(yq -r \
    '[.. | anchor] | map(select(. != "")) | unique | .[]' "$values_file")
  while IFS= read -r anchor_name; do
    [[ -n "$anchor_name" ]] && anchor_names+=("$anchor_name")
  done <<<"$anchor_names_output"

  [[ ${#anchor_names[@]} -gt 0 ]] || return 0

  yq --yaml-fix-merge-anchor-to-spec=true -o=json -I=0 '.' "$values_file" \
    | jq -cS '.' >"$BEFORE_EXPANSION_JSON"
  yq --yaml-fix-merge-anchor-to-spec=true 'explode(.)' \
    "$values_file" >"$EXPANDED_FILE"
  yq --yaml-fix-merge-anchor-to-spec=true -o=json -I=0 '.' "$EXPANDED_FILE" \
    | jq -cS '.' >"$AFTER_EXPANSION_JSON"
  cmp -s "$BEFORE_EXPANSION_JSON" "$AFTER_EXPANSION_JSON" \
    || fail "expanding YAML anchors changed the resolved values structure: $display_name"
  cp "$EXPANDED_FILE" "$values_file"

  printf 'Warning: expanded YAML anchors and aliases in %s; they will not be preserved in the output.\n' \
    "$display_name" >&2
  printf 'Expanded anchors:\n' >&2
  printf '  %s\n' "${anchor_names[@]}" >&2
}

# Convert only fields with a direct package-values equivalent. In particular,
# valuesFrom needs external resources, and replacing dependency/post-renderer
# lists is not equivalent to letting the chart generate or append them.
convert_helmrelease_patches() {
  local patch_file document_count document_index display_name release_name
  local package_name package_metadata template_directory unsupported_fields
  local patch_document="$PATCH_WORK_DIR/document.yaml"
  local patch_json="$PATCH_WORK_DIR/document.json"
  local converted_patch="$PATCH_WORK_DIR/converted.yaml"

  printf '{}\n' >"$PATCH_WORK_DIR/values.yaml"
  [[ ${#HELMRELEASE_PATCH_FILES[@]} -gt 0 ]] || return 0
  for patch_file in "${HELMRELEASE_PATCH_FILES[@]}"; do
    document_count=$(yq eval-all --no-doc '1' "$patch_file" 2>/dev/null | wc -l | tr -d '[:space:]') \
      || fail "HelmRelease patch is not valid YAML: $patch_file"
    for ((document_index=0; document_index<document_count; document_index++)); do
      display_name="$patch_file document $((document_index + 1))"
      DOCUMENT_INDEX="$document_index" yq 'select(documentIndex == env(DOCUMENT_INDEX))' \
        "$patch_file" >"$patch_document"
      expand_yaml_anchors "$patch_document" "$display_name"
      yq -o=json '.' "$patch_document" >"$patch_json"
      jq -e 'type == "object" and (has("sops") | not)' "$patch_json" >/dev/null \
        || fail "expected a decrypted HelmRelease mapping: $display_name"
      jq -e '.kind == "HelmRelease" and
        (.apiVersion == "helm.toolkit.fluxcd.io/v2" or
         .apiVersion == "helm.toolkit.fluxcd.io/v2beta2" or
         .apiVersion == "helm.toolkit.fluxcd.io/v2beta1") and
        (.metadata | type == "object") and (.metadata.name | type == "string") and
        (.spec | type == "object")' "$patch_json" >/dev/null \
        || fail "expected a Flux package HelmRelease with metadata.name and a spec mapping: $display_name"

      unsupported_fields=$(jq -r '[
        (keys[] | select(. != "apiVersion" and . != "kind" and . != "metadata" and . != "spec")),
        (.metadata | keys[] | select(. != "name" and . != "namespace") | "metadata." + .),
        (.spec | keys[] | select(IN("values", "interval", "timeout", "install", "upgrade",
          "rollback", "uninstall", "test", "driftDetection", "suspend", "maxHistory",
          "persistentClient", "serviceAccountName") | not) | "spec." + .)
      ] | join(", ")' "$patch_json")
      [[ -z "$unsupported_fields" ]] \
        || fail "unsupported HelmRelease patch fields ($unsupported_fields): $display_name; migrate these manually; no output written"
      jq -e '(.spec | has("values") | not) or (.spec.values | type == "object")' "$patch_json" >/dev/null \
        || fail "spec.values must be a mapping: $display_name"
      # Nulls and Kustomize directives are patch operations, not ordinary values.
      jq -e '[.spec | paths as $p | select((getpath($p) == null) or
        ($p[-1] | type == "string" and startswith("$")))] | length == 0' "$patch_json" >/dev/null \
        || fail "null deletions and patch directives require manual migration: $display_name"

      release_name=$(jq -r '.metadata.name' "$patch_json")
      package_name=""
      for package_metadata in "${BUILTIN_PACKAGE_METADATA[@]}"; do
        template_directory=${package_metadata#*|}
        # Gateways have dynamically named, per-instance HelmReleases.
        [[ "$template_directory" != istio-gateway ]] || continue
        [[ "$template_directory" != elasticsearch-kibana ]] || template_directory=ek
        if [[ "$release_name" == "$template_directory" ]]; then
          package_name=${package_metadata%%|*}
          break
        fi
      done
      [[ -n "$package_name" ]] \
        || fail "cannot identify a built-in package from HelmRelease '$release_name': $display_name; migrate custom packages, gateways, and parent Big Bang patches manually"

      PACKAGE_NAME="$package_name" yq '
        .spec as $spec |
        {"packages": {(strenv(PACKAGE_NAME)): {}}} |
        (select($spec | has("values")) | .packages[strenv(PACKAGE_NAME)].values) = $spec.values |
        ($spec | del(.values)) as $flux |
        (select($flux | length > 0) | .packages[strenv(PACKAGE_NAME)].flux) = $flux
      ' "$patch_document" >"$converted_patch"
      yq eval-all '. as $item ireduce ({}; . * $item)' \
        "$PATCH_WORK_DIR/values.yaml" "$converted_patch" >"$PATCH_WORK_DIR/merged.yaml"
      mv "$PATCH_WORK_DIR/merged.yaml" "$PATCH_WORK_DIR/values.yaml"
      printf 'Converted HelmRelease %s -> packages.%s (%s)\n' \
        "$release_name" "$package_name" "$display_name" >&2
    done
  done
}

convert_helmrelease_patches

if [[ "$BIGBANG_HELMRELEASE" == true ]]; then
  BIGBANG_HELMRELEASE_FILE="$PATCH_WORK_DIR/bigbang.yaml"
  cp "${INPUT_FILES[0]}" "$BIGBANG_HELMRELEASE_FILE"
  expand_yaml_anchors "$BIGBANG_HELMRELEASE_FILE" "${INPUT_FILES[0]} HelmRelease envelope"
  if yq -e '.spec | has("values")' "$BIGBANG_HELMRELEASE_FILE" >/dev/null 2>&1; then
    BIGBANG_HAS_VALUES=true
    yq '.spec.values' "$BIGBANG_HELMRELEASE_FILE" >"$WORK_FILE"
    validate_values_file "$WORK_FILE" "${INPUT_FILES[0]}:spec.values"
    # Preserve nested nulls (for example resource-limit deletions), but refuse
    # patch operations on the maps whose contents the migration rearranges.
    yq -e '[to_entries[] | select(.key == "packages" or .key == "addons" or
      .key == "packageConfiguration") | select(.value | tag != "!!map")] | length == 0' \
      "$WORK_FILE" >/dev/null 2>&1 \
      || fail "null package-container deletions require manual migration: ${INPUT_FILES[0]}:spec.values"
    yq -o=json '.' "$WORK_FILE" | jq -e '[.. | objects | keys[] |
      select(. == "$patch" or . == "$retainKeys" or
        startswith("$deleteFromPrimitiveList/") or startswith("$setElementOrder/"))] |
      length == 0' >/dev/null \
      || fail "Kustomize directives inside spec.values require manual migration: ${INPUT_FILES[0]}"
  else
    BIGBANG_HAS_VALUES=false
    printf '{}\n' >"$WORK_FILE"
    printf 'No inline spec.values found; preserving HelmRelease without adding values.\n' >&2
  fi
elif [[ -n "$SECRET_VALUES_KEY" ]]; then
  cp "${INPUT_FILES[0]}" "$SECRET_WORK_FILE"
  expand_yaml_anchors "$SECRET_WORK_FILE" "${INPUT_FILES[0]} Secret envelope"
  HAS_STRING_DATA=$(SECRET_VALUES_KEY="$SECRET_VALUES_KEY" yq -r \
    '(.stringData // {}) | has(strenv(SECRET_VALUES_KEY))' "$SECRET_WORK_FILE")
  HAS_DATA=$(SECRET_VALUES_KEY="$SECRET_VALUES_KEY" yq -r \
    '(.data // {}) | has(strenv(SECRET_VALUES_KEY))' "$SECRET_WORK_FILE")

  if [[ "$HAS_STRING_DATA" == true && "$HAS_DATA" == true ]]; then
    fail "Secret key ${SECRET_VALUES_KEY} exists in both data and stringData"
  elif [[ "$HAS_STRING_DATA" == true ]]; then
    SECRET_VALUES_FIELD=stringData
    SECRET_VALUES_KEY="$SECRET_VALUES_KEY" yq -r -0 \
      '.stringData[strenv(SECRET_VALUES_KEY)]' "$SECRET_WORK_FILE" \
      | tr -d '\000' >"$WORK_FILE"
  elif [[ "$HAS_DATA" == true ]]; then
    SECRET_VALUES_FIELD=data
    SECRET_VALUES_KEY="$SECRET_VALUES_KEY" yq -r -0 \
      '.data[strenv(SECRET_VALUES_KEY)]' "$SECRET_WORK_FILE" \
      | tr -d '\000' \
      | tr -d '[:space:]' >"$BASE64_INPUT"
    if ! grep -Eq '^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$' \
      "$BASE64_INPUT" \
      || ! decode_base64 <"$BASE64_INPUT" >"$WORK_FILE"; then
      fail "data.${SECRET_VALUES_KEY} is not valid base64"
    fi
  else
    fail "Secret does not contain ${SECRET_VALUES_KEY} in data or stringData"
  fi
  validate_values_file "$WORK_FILE" "${INPUT_FILES[0]}:${SECRET_VALUES_KEY}"
elif [[ ${#INPUT_FILES[@]} -eq 0 ]]; then
  printf '{}\n' >"$WORK_FILE"
elif [[ ${#INPUT_FILES[@]} -eq 1 ]]; then
  cp "${INPUT_FILES[0]}" "$WORK_FILE"
else
  yq --yaml-fix-merge-anchor-to-spec=true eval-all \
    '. as $item ireduce ({}; . * $item)' "${INPUT_FILES[@]}" >"$WORK_FILE"
fi

if [[ "$BIGBANG_HELMRELEASE" == true ]]; then
  ANCHOR_DISPLAY_NAME="${INPUT_FILES[0]}:spec.values"
elif [[ -n "$SECRET_VALUES_KEY" ]]; then
  ANCHOR_DISPLAY_NAME="${INPUT_FILES[0]}:${SECRET_VALUES_KEY}"
elif [[ ${#INPUT_FILES[@]} -eq 1 ]]; then
  ANCHOR_DISPLAY_NAME="${INPUT_FILES[0]}"
else
  ANCHOR_DISPLAY_NAME="composed values input"
fi
expand_yaml_anchors "$WORK_FILE" "$ANCHOR_DISPLAY_NAME"

# Before v1 is enabled, every packages.<name> entry has the 3.x custom-package
# meaning. Refuse both exact and normalized collisions before enabling v1 so
# migration cannot produce values that the chart will reject. Values already
# using v1 receive the same normalized collision validation as chart rendering.
CANONICAL_PACKAGES_ENABLED=false
if [[ "$OMIT_PACKAGE_CONFIGURATION" == true ]] \
  || yq -e '.packageConfiguration.version == "v1"' "$WORK_FILE" >/dev/null 2>&1; then
  CANONICAL_PACKAGES_ENABLED=true
fi

CUSTOM_PACKAGE_NAMES=()
CUSTOM_PACKAGE_RESOURCE_NAMES=()
while IFS= read -r package_name; do
  if is_builtin_package "$package_name"; then
    if [[ "$CANONICAL_PACKAGES_ENABLED" != true ]]; then
      fail "packages.${package_name} is an existing 3.x custom package that conflicts with a canonical built-in name; rename it or explicitly set packageConfiguration.version to v1 before migrating"
    fi
    continue
  fi

  package_lower=$(lower_package_name "$package_name")
  package_resource_identity=$(package_resource_name "$package_name")

  for package_metadata in "${BUILTIN_PACKAGE_METADATA[@]}"; do
    builtin_name=${package_metadata%%|*}
    template_directory=${package_metadata#*|}
    builtin_lower=$(lower_package_name "$builtin_name")
    builtin_resource_name=$(package_resource_name "$builtin_name")
    template_directory_lower=$(lower_package_name "$template_directory")

    if [[ "$package_lower" == "$builtin_lower" \
      || "$package_lower" == "$builtin_resource_name" \
      || "$package_lower" == "$template_directory_lower" \
      || "$package_resource_identity" == "$builtin_lower" \
      || "$package_resource_identity" == "$builtin_resource_name" \
      || "$package_resource_identity" == "$template_directory_lower" ]]; then
      fail "packages.${package_name} conflicts with built-in package packages.${builtin_name}; use the canonical name packages.${builtin_name}"
    fi
  done

  for custom_index in "${!CUSTOM_PACKAGE_RESOURCE_NAMES[@]}"; do
    if [[ "$package_resource_identity" == "${CUSTOM_PACKAGE_RESOURCE_NAMES[$custom_index]}" ]]; then
      fail "packages.${CUSTOM_PACKAGE_NAMES[$custom_index]} and packages.${package_name} normalize to the same package identity"
    fi
  done
  CUSTOM_PACKAGE_NAMES+=("$package_name")
  CUSTOM_PACKAGE_RESOURCE_NAMES+=("$package_resource_identity")
done < <(yq -r '.packages // {} | keys | .[]' "$WORK_FILE")

capture_package_order "$WORK_FILE"

if [[ "$OMIT_PACKAGE_CONFIGURATION" == true ]]; then
  yq -i 'del(.packageConfiguration)' "$WORK_FILE"
else
  yq -i '.packageConfiguration = (.packageConfiguration // {}) | .packageConfiguration.version = "v1"' "$WORK_FILE"
fi

MIGRATED_PATHS=()

for package_name in "${ROOT_PACKAGES[@]}"; do
  if PACKAGE_NAME="$package_name" yq -e 'has(strenv(PACKAGE_NAME))' "$WORK_FILE" >/dev/null 2>&1; then
    if [[ "$BIGBANG_HELMRELEASE" == true ]]; then
      PACKAGE_NAME="$package_name" yq -e '
        (.[strenv(PACKAGE_NAME)] | tag == "!!map") and
        (((.packages // {}) | has(strenv(PACKAGE_NAME)) | not) or
         (.packages[strenv(PACKAGE_NAME)] | tag == "!!map"))' "$WORK_FILE" >/dev/null 2>&1 \
        || fail "package-map deletions require manual migration: ${INPUT_FILES[0]}:spec.values.$package_name"
    fi
    PACKAGE_NAME="$package_name" yq -i '
      .packages = (.packages // {}) |
      .packages[strenv(PACKAGE_NAME)] =
        ((.[strenv(PACKAGE_NAME)] // {}) * (.packages[strenv(PACKAGE_NAME)] // {})) |
      del(.[strenv(PACKAGE_NAME)])
    ' "$WORK_FILE"
    MIGRATED_PATHS+=("$package_name -> packages.$package_name")
  fi
done

# The deprecated lowercase spelling is still accepted by the 3.x templates.
# Normalize it first so the supported spelling, and then the canonical package
# path, retain their existing precedence.
if yq -e '.addons | has("mattermostoperator")' "$WORK_FILE" >/dev/null 2>&1; then
  if [[ "$BIGBANG_HELMRELEASE" == true ]]; then
    yq -e '(.addons.mattermostoperator | tag == "!!map") and
      ((.addons | has("mattermostOperator") | not) or
       (.addons.mattermostOperator | tag == "!!map"))' "$WORK_FILE" >/dev/null 2>&1 \
      || fail "package-map deletions require manual migration: ${INPUT_FILES[0]}:spec.values.addons.mattermostoperator"
  fi
  yq -i '
    .addons.mattermostOperator =
      ((.addons.mattermostoperator // {}) * (.addons.mattermostOperator // {})) |
    del(.addons.mattermostoperator)
  ' "$WORK_FILE"
  MIGRATED_PATHS+=("addons.mattermostoperator -> packages.mattermostOperator")
fi

for package_name in "${ADDON_PACKAGES[@]}"; do
  if PACKAGE_NAME="$package_name" yq -e '.addons | has(strenv(PACKAGE_NAME))' "$WORK_FILE" >/dev/null 2>&1; then
    if [[ "$BIGBANG_HELMRELEASE" == true ]]; then
      PACKAGE_NAME="$package_name" yq -e '
        (.addons[strenv(PACKAGE_NAME)] | tag == "!!map") and
        (((.packages // {}) | has(strenv(PACKAGE_NAME)) | not) or
         (.packages[strenv(PACKAGE_NAME)] | tag == "!!map"))' "$WORK_FILE" >/dev/null 2>&1 \
        || fail "package-map deletions require manual migration: ${INPUT_FILES[0]}:spec.values.addons.$package_name"
    fi
    PACKAGE_NAME="$package_name" yq -i '
      .packages = (.packages // {}) |
      .packages[strenv(PACKAGE_NAME)] =
        ((.addons[strenv(PACKAGE_NAME)] // {}) * (.packages[strenv(PACKAGE_NAME)] // {})) |
      del(.addons[strenv(PACKAGE_NAME)])
    ' "$WORK_FILE"
    MIGRATED_PATHS+=("addons.$package_name -> packages.$package_name")
  fi
done

if [[ ${#HELMRELEASE_PATCH_FILES[@]} -gt 0 ]]; then
  yq eval-all '. as $item ireduce ({}; . * $item)' \
    "$WORK_FILE" "$PATCH_WORK_DIR/values.yaml" >"$PATCH_WORK_DIR/result.yaml"
  cp "$PATCH_WORK_DIR/result.yaml" "$WORK_FILE"
fi

SERVICE_ENTRY_REVIEW=()
HOST_MIGRATION_REVIEW=()
if [[ "$TARGET_VERSION" == 4 ]]; then
  # Big Bang 4.x packages consume bb-common as a subchart. Move the values that
  # belonged to the former library chart into the subchart's values scope after
  # legacy and canonical package paths have been merged.
  for package_name in "${ROOT_PACKAGES[@]}" "${ADDON_PACKAGES[@]}"; do
    for value_key in istio networkPolicies routes; do
      if PACKAGE_NAME="$package_name" VALUE_KEY="$value_key" yq -e '
        (.packages[strenv(PACKAGE_NAME)].values | tag == "!!map") and
        (.packages[strenv(PACKAGE_NAME)].values | has(strenv(VALUE_KEY)))
      ' "$WORK_FILE" >/dev/null 2>&1; then
        PACKAGE_NAME="$package_name" VALUE_KEY="$value_key" yq -i '
          .packages[strenv(PACKAGE_NAME)].values |= (
            ."bb-common" = (."bb-common" // {}) |
            ."bb-common"[strenv(VALUE_KEY)] =
              ((.[strenv(VALUE_KEY)] // {}) *
               (."bb-common"[strenv(VALUE_KEY)] // {})) |
            del(.[strenv(VALUE_KEY)])
          )
        ' "$WORK_FILE"

        MIGRATED_PATHS+=(
          "packages.$package_name.values.$value_key -> packages.$package_name.values.bb-common.$value_key"
        )
      fi
    done
  done

  migrate_inbound_hosts

  # Final legacy cleanup and hardened removal to ensure bb-common usage is schema valid.
  for package_name in "${ROOT_PACKAGES[@]}" "${ADDON_PACKAGES[@]}"; do
    PACKAGE_NAME="$package_name" yq -e \
      '.packages[strenv(PACKAGE_NAME)].values.bb-common.istio | tag == "!!map"' \
      "$WORK_FILE" >/dev/null 2>&1 || continue

    # Capture the legacy ServiceEntry names before they are folded in — these stay
    # cluster-wide under serviceEntries.custom and are flagged for review afterwards.
    hardened_se_names=$(PACKAGE_NAME="$package_name" yq -r '
      (.packages[strenv(PACKAGE_NAME)].values.bb-common.istio.hardened.customServiceEntries // [])
      | select(length > 0)
      | map(.name // "(unnamed)") | join(", ")
    ' "$WORK_FILE")
    hardened_authz_count=$(PACKAGE_NAME="$package_name" yq -r '
      (.packages[strenv(PACKAGE_NAME)].values.bb-common.istio.hardened.customAuthorizationPolicies // [])
      | length
    ' "$WORK_FILE")

    PACKAGE_NAME="$package_name" yq -i '
      with(.packages[strenv(PACKAGE_NAME)].values.bb-common.istio;
          with(select((.hardened.customServiceEntries // []) | length > 0);
            .serviceEntries.custom =
              (.hardened.customServiceEntries + (.serviceEntries.custom // [])))
        | with(select((.hardened.customAuthorizationPolicies // []) | length > 0);
            .authorizationPolicies.custom =
              (.hardened.customAuthorizationPolicies + (.authorizationPolicies.custom // [])))
        | del(.hardened)
      )
    ' "$WORK_FILE"

    if [[ -n "$hardened_se_names" ]]; then
      MIGRATED_PATHS+=("packages.$package_name.values.bb-common.istio.hardened.customServiceEntries -> serviceEntries.custom")
      # istiod's ServiceEntries were always intended to be global, so don't prompt a review for it.
      if [[ "$package_name" != "istiod" ]]; then
        SERVICE_ENTRY_REVIEW+=("packages.$package_name.values.bb-common.istio.serviceEntries.custom: $hardened_se_names")
      fi
    fi
    if [[ "$hardened_authz_count" -gt 0 ]]; then
      MIGRATED_PATHS+=("packages.$package_name.values.bb-common.istio.hardened.customAuthorizationPolicies -> authorizationPolicies.custom")
    fi
  done

  # Remove deprecated global hardening key from istiod.
  if yq -e '.packages.istiod.values | has("hardened")' "$WORK_FILE" >/dev/null 2>&1; then
    istiod_hardened_authz_count=$(yq -r '
      (.packages.istiod.values.hardened.customAuthorizationPolicies // []) | length
    ' "$WORK_FILE")

    yq -i '
      with(.packages.istiod.values;
          with(select((.hardened.customAuthorizationPolicies // []) | length > 0);
            ."bb-common".istio.authorizationPolicies.custom =
              (.hardened.customAuthorizationPolicies +
               (."bb-common".istio.authorizationPolicies.custom // [])))
        | del(.hardened)
      )
    ' "$WORK_FILE"

    if [[ "$istiod_hardened_authz_count" -gt 0 ]]; then
      MIGRATED_PATHS+=("packages.istiod.values.hardened.customAuthorizationPolicies -> packages.istiod.values.bb-common.istio.authorizationPolicies.custom")
    fi
    yq -i 'del(.packages.istiod.values | select(tag == "!!map" and length == 0))' "$WORK_FILE"
    MIGRATED_PATHS+=("packages.istiod.values.hardened -> removed (hardening deprecated in 4.x)")
  fi
fi

if yq -e '(.addons | tag == "!!map") and (.addons | length == 0)' "$WORK_FILE" >/dev/null 2>&1; then
  yq -i 'del(.addons)' "$WORK_FILE"
fi

reorder_packages "$WORK_FILE"

RESULT_FILE=$WORK_FILE
if [[ "$BIGBANG_HELMRELEASE" == true ]]; then
  if [[ "$BIGBANG_HAS_VALUES" == true ]]; then
    MIGRATED_VALUES_FILE="$WORK_FILE" yq -i '.spec.values = load(strenv(MIGRATED_VALUES_FILE))' \
      "$BIGBANG_HELMRELEASE_FILE"
  fi
  RESULT_FILE=$BIGBANG_HELMRELEASE_FILE
elif [[ -n "$SECRET_VALUES_KEY" ]]; then
  if [[ "$SECRET_VALUES_FIELD" == data ]]; then
    base64 <"$WORK_FILE" | tr -d '\n' >"$SECRET_VALUE_FILE"
  else
    cp "$WORK_FILE" "$SECRET_VALUE_FILE"
  fi
  SECRET_VALUES_FIELD="$SECRET_VALUES_FIELD" \
  SECRET_VALUES_KEY="$SECRET_VALUES_KEY" \
  SECRET_VALUE_FILE="$SECRET_VALUE_FILE" \
    yq -i '
      .[strenv(SECRET_VALUES_FIELD)][strenv(SECRET_VALUES_KEY)] =
        load_str(strenv(SECRET_VALUE_FILE))
    ' "$SECRET_WORK_FILE"
  RESULT_FILE=$SECRET_WORK_FILE
fi

if [[ "$IN_PLACE" == true ]]; then
  INPUT_FILE=${INPUT_FILES[0]}
  BACKUP_FILE="${INPUT_FILE}.bak"
  [[ ! -e "$BACKUP_FILE" ]] || fail "backup already exists: $BACKUP_FILE"
  cp -p "$INPUT_FILE" "$BACKUP_FILE"
  cp "$RESULT_FILE" "$INPUT_FILE"
  printf 'Migrated %s; backup written to %s\n' "$INPUT_FILE" "$BACKUP_FILE" >&2
elif [[ -n "$OUTPUT_FILE" ]]; then
  cp "$RESULT_FILE" "$OUTPUT_FILE"
  printf 'Migrated values written to %s\n' "$OUTPUT_FILE" >&2
else
  cat "$RESULT_FILE"
fi

if [[ ${#MIGRATED_PATHS[@]} -eq 0 ]]; then
  printf 'No legacy built-in package paths found.\n' >&2
else
  printf 'Migrated package paths:\n' >&2
  printf '  %s\n' "${MIGRATED_PATHS[@]}" >&2
fi

if [[ ${#SERVICE_ENTRY_REVIEW[@]} -gt 0 ]]; then
  printf '\nReview: the following ServiceEntries were migrated from hardened.customServiceEntries and\n' >&2
  printf 'remain cluster-wide (istio.serviceEntries.custom). If namespace-scoped egress is sufficient,\n' >&2
  printf "consider moving each to that package's bb-common.routes.outbound instead:\n" >&2
  printf '  %s\n' "${SERVICE_ENTRY_REVIEW[@]}" >&2
  printf '\nReference: https://docs-bigbang.dso.mil/latest/library-charts/bb-common/docs/routes/\n' >&2
fi

if [[ ${#HOST_MIGRATION_REVIEW[@]} -gt 0 ]]; then
  printf '\nReview: the following legacy Istio hosts require manual migration:\n' >&2
  printf '  %s\n' "${HOST_MIGRATION_REVIEW[@]}" >&2
fi
